const msg = $input.first().json.message || {};
const chatId = msg.chat && msg.chat.id;
if (!chatId) return [];
const text = (msg.text || '').trim();
const doc = msg.document;
const st = $getWorkflowStaticData('global');
if (!st.users) st.users = {};
if (!st.users[chatId]) st.users[chatId] = {};
const u = st.users[chatId];
const out = (o) => [{ json: { chatId, ...o } }];
const reply = (t) => out({ route: 'reply', reply: t });
const EX = 'ACBDACBDACBDACBDACBD';
const HELP = 'Hey! 👋 I turn your study material into a 20-question MCQ quiz and email you your score.\n\n1) Send me your email address.\n2) Send a PDF (or paste your notes as text).\n3) I send the quiz. Reply with ALL answers in ONE message, like: ' + EX + '\n\nSend /start anytime to see this again.';
if (text.startsWith('/start') || text.startsWith('/help')) return reply(HELP);
if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) {
  u.email = text.toLowerCase();
  return reply('Email saved ✅ ' + u.email + '\nNow send me a PDF, or paste your notes as text.');
}
if (doc) {
  if (!u.email) return reply('First send me your email address (I email your score there). Then send the file again.');
  const name = (doc.file_name || '').toLowerCase();
  const mime = (doc.mime_type || '').toLowerCase();
  if (!(name.endsWith('.pdf') || mime === 'application/pdf')) return reply('I can read PDF files only. For Word/PPT/TXT, copy the text and paste it here as a message.');
  if ((doc.file_size || 0) > 10 * 1024 * 1024) return reply('That PDF is over 10 MB. Send a smaller one or paste the text.');
  return out({ route: 'doc', source: 'file', fileId: doc.file_id });
}
if (text) {
  if (u.quiz && /^[\s\d.,:;)\-A-Da-d]+$/.test(text) && /[A-Da-d]/.test(text)) {
    const letters = (text.replace(/\d+/g, '').match(/[A-Da-d]/g) || []).map((c) => c.toUpperCase());
    const n = u.quiz.length;
    if (letters.length !== n) return reply('I counted ' + letters.length + ' answers but the quiz has ' + n + ' questions. Send all ' + n + ' letters again in ONE message, like: ' + EX.slice(0, n));
    return out({ route: 'answers', letters });
  }
  if (text.length >= 300) {
    if (!u.email) return reply('First send me your email address (I email your score there). Then paste your notes again.');
    return out({ route: 'doc', source: 'text', rawText: text });
  }
  return reply(u.email ? 'Send a PDF, or paste at least a few paragraphs of notes (300+ characters). Send /start for help.' : 'Send your email address first. Send /start for help.');
}
return reply('I understand text and PDF files only 🙂 Send /start for help.');

const r = $('ROUTER').first().json;
const j = $input.first().json || {};
let raw = r.source === 'text' ? (r.rawText || '') : (j.text || '');
raw = String(raw).replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

if (raw.length < 300) {
  return [{ json: { ok: false, chatId: r.chatId, reply: 'I could not read enough text from that (scanned or image-only PDFs have no text). Send a text-based PDF, or paste your notes as a message.' } }];
}

const LIMIT = 9000, CH = 750;
let ctx = raw;

if (raw.length > LIMIT) {
  const chunks = [];
  for (let i = 0; i < raw.length; i += CH) chunks.push(raw.slice(i, i + CH));
  const take = Math.floor(LIMIT / CH);
  const picked = [];
  for (let k = 0; k < take; k++) picked.push(chunks[Math.floor((k * chunks.length) / take)]);
  ctx = picked.join('\n...\n');
}

return [{ json: { ok: true, chatId: r.chatId, context: ctx } }];

const chatId = $('Prep').first().json.chatId;
const fail = (t) => [{ json: { chatId, reply: t } }];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let raw = $input.first().json.text;
if (!raw || typeof raw !== 'string') return fail('The AI was busy (rate limit). Wait 1 minute, then send the document again.');

raw = raw.replace(/\x60{3}(json)?/gi, '').trim();
let arr;

try {
  arr = JSON.parse(raw.slice(raw.indexOf('['), raw.lastIndexOf(']') + 1));
} catch (e) {
  return fail('I could not build the quiz this time. Please send the document again.');
}

const L = ['A', 'B', 'C', 'D'];
const qs = [];

for (const x of (Array.isArray(arr) ? arr : [])) {
  try {
    const o = x.options;
    const opts = Array.isArray(o) ? o.map(String) : L.map((k) => (o && o[k] != null ? String(o[k]) : ''));
    if (opts.length !== 4 || opts.some((v) => !v.trim()) || !x.q) continue;

    const a = String(x.answer || '').trim().toUpperCase().charAt(0);
    if (!L.includes(a)) continue;

    qs.push({
      q: String(x.q).trim().slice(0, 400),
      o: opts.map((s) => s.replace(/^[A-D][.)]\s*/, '').trim().slice(0, 200)),
      a,
      why: String(x.why || '').trim().slice(0, 200)
    });
  } catch (e) {}
}

if (qs.length < 10) return fail('I could not make enough good questions from that. Try a longer, clearer document.');

const quiz = qs.slice(0, 20);
const st = $getWorkflowStaticData('global');

if (!st.users) st.users = {};
if (!st.users[chatId]) st.users[chatId] = {};
st.users[chatId].quiz = quiz;

const n = quiz.length;
const msgs = ['📝 Quiz ready: ' + n + ' questions. Read them below, then reply with ALL answers in ONE message, like: ' + 'ACBDACBDACBDACBDACBD'.slice(0, n)];

let cur = '';

quiz.forEach((x, i) => {
  const b = (i + 1) + '. ' + esc(x.q) + '\nA) ' + esc(x.o[0]) + '\nB) ' + esc(x.o[1]) + '\nC) ' + esc(x.o[2]) + '\nD) ' + esc(x.o[3]);

  if (cur && (cur + '\n\n' + b).length > 3500) {
    msgs.push(cur);
    cur = b;
  } else {
    cur = cur ? cur + '\n\n' + b : b;
  }
});

if (cur) msgs.push(cur);

return msgs.map((t) => ({ json: { chatId, reply: t } }));

const r = $('ROUTER').first().json;
const chatId = r.chatId;
const letters = r.letters;
const u = $getWorkflowStaticData('global').users[chatId];
const quiz = u && u.quiz;

if (!quiz || !Array.isArray(quiz)) {
  return [{ json: { chatId, reply: 'I could not find your quiz. Please send your study material again.' } }];
}

const n = quiz.length;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let score = 0;
const wrong = [];

quiz.forEach((x, i) => {
  if (letters[i] === x.a) score++;
  else wrong.push({
    i: i + 1,
    yours: letters[i],
    right: x.a,
    ans: x.o['ABCD'.indexOf(x.a)],
    why: x.why
  });
});

const pct = Math.round((score / n) * 100);
const em = pct >= 80 ? '🏆' : pct >= 50 ? '👍' : '📚';

let tg = em + ' <b>Score: ' + score + '/' + n + ' (' + pct + '%)</b>\n';
let mail = 'Your quiz score: ' + score + '/' + n + ' (' + pct + '%)\n\n';

if (wrong.length) {
  tg += '\nReview:\n';
  mail += 'Questions to review:\n\n';
} else {
  tg += '\nPerfect score! 🎉\n';
  mail += 'Perfect score! Well done.\n';
}

for (const w of wrong) {
  tg += '\n' + w.i + '. You: ' + w.yours + ' | Correct: ' + w.right + ') ' + esc(w.ans) + '\n' + esc(w.why) + '\n';
  mail += w.i + '. Your answer: ' + w.yours + ' | Correct: ' + w.right + ') ' + w.ans + '\n   ' + w.why + '\n\n';
}

if (tg.length > 3600) tg = tg.slice(0, tg.lastIndexOf('\n', 3600)) + '\n…';

tg += '\n📧 Emailing this to ' + esc(u.email || 'you') + ' (check Spam).\nSend another PDF or notes for a new quiz.';

return [{
  json: {
    chatId,
    reply: tg,
    email: u.email,
    subject: 'Your quiz score: ' + score + '/' + n + ' (' + pct + '%)',
    mail
  }
}];
